// ============================================================================
// FlexRay_apb: APB4 register wrapper around FlexRay_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/FlexRay.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/FlexRay.md
// ============================================================================
module FlexRay_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic rxd,
  output logic txd,
  output logic tx_en
);
  localparam logic [31:0] ID_VALUE = 32'h46520200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [16:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd17) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [3:0]    c_cfg_spc;
  logic [3:0]    c_cfg_tss;
  logic [9:0]    c_cfg_slot;
  logic [5:0]    c_cfg_ap;
  logic [5:0]    c_cfg_nslots;
  logic [9:0]    c_cfg_nit;
  logic [3:0]    c_cfg_plen;
  logic [5:0]    c_cfg_my_slot;
  logic          c_cfg_sync;
  logic          c_cfg_cold;
  logic          c_cfg_chan_b;
  logic [7:0]    c_cfg_corr;
  logic          c_tx_valid;
  logic          c_tx_ready;
  logic [127:0]  c_tx_data;
  logic          c_tx_done;
  logic          c_rx_valid;
  logic [5:0]    c_rx_id;
  logic [5:0]    c_rx_cycle;
  logic [6:0]    c_rx_len;
  logic          c_rx_null;
  logic          c_rx_sync;
  logic          c_rx_startup;
  logic [127:0]  c_rx_data;
  logic          c_synced;
  logic [5:0]    c_cycle;
  logic [5:0]    c_slot;
  logic          c_cycle_start;
  logic          c_err_coding;
  logic          c_err_hcrc;
  logic          c_err_fcrc;
  logic          c_err_slot;
  logic          c_err_sync;
  FlexRay_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .rxd(rxd),
    .txd(txd),
    .tx_en(tx_en),
    .cfg_spc(c_cfg_spc),
    .cfg_tss(c_cfg_tss),
    .cfg_slot(c_cfg_slot),
    .cfg_ap(c_cfg_ap),
    .cfg_nslots(c_cfg_nslots),
    .cfg_nit(c_cfg_nit),
    .cfg_plen(c_cfg_plen),
    .cfg_my_slot(c_cfg_my_slot),
    .cfg_sync(c_cfg_sync),
    .cfg_cold(c_cfg_cold),
    .cfg_chan_b(c_cfg_chan_b),
    .cfg_corr(c_cfg_corr),
    .tx_valid(c_tx_valid),
    .tx_ready(c_tx_ready),
    .tx_data(c_tx_data),
    .tx_done(c_tx_done),
    .rx_valid(c_rx_valid),
    .rx_id(c_rx_id),
    .rx_cycle(c_rx_cycle),
    .rx_len(c_rx_len),
    .rx_null(c_rx_null),
    .rx_sync(c_rx_sync),
    .rx_startup(c_rx_startup),
    .rx_data(c_rx_data),
    .synced(c_synced),
    .cycle(c_cycle),
    .slot(c_slot),
    .cycle_start(c_cycle_start),
    .err_coding(c_err_coding),
    .err_hcrc(c_err_hcrc),
    .err_fcrc(c_err_fcrc),
    .err_slot(c_err_slot),
    .err_sync(c_err_sync)
  );

  // ---------------- registers ----------------
  logic [10:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [29:0] r_CFG0;   // 12'h014 CFG0
  logic [30:0] r_CFG1;   // 12'h018 CFG1
  logic [31:0] h_TX0;   // 12'h01C TX0 holding register
  logic [31:0] h_TX1;   // 12'h020 TX1 holding register
  logic [31:0] h_TX2;   // 12'h024 TX2 holding register
  logic [31:0] h_TX3;   // 12'h028 TX3 holding register
  logic [31:0] h_RX0;   // 12'h02C RX0 holding register
  logic [31:0] h_RX1;   // 12'h030 RX1 holding register
  logic [31:0] h_RX2;   // 12'h034 RX2 holding register
  logic [31:0] h_RX3;   // 12'h038 RX3 holding register
  logic [21:0] h_RX4;   // 12'h03C RX4 holding register
  logic full_TX;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CFG0 <= 30'h8307850;
      r_CFG1 <= 31'h2000001E;
      h_TX0 <= '0;
      h_TX1 <= '0;
      h_TX2 <= '0;
      h_TX3 <= '0;
      h_RX0 <= '0;
      h_RX1 <= '0;
      h_RX2 <= '0;
      h_RX3 <= '0;
      h_RX4 <= '0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[10:0] & wmask[10:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[10:0]) | (PWDATA[10:0] & wmask[10:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CFG0 <= (r_CFG0 & ~wmask[29:0]) | (PWDATA[29:0] & wmask[29:0]);
      if (wr && hit[6]) r_CFG1 <= (r_CFG1 & ~wmask[30:0]) | (PWDATA[30:0] & wmask[30:0]);
      if (wr && hit[7] && !full_TX) h_TX0 <= (h_TX0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8] && !full_TX) h_TX1 <= (h_TX1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9] && !full_TX) h_TX2 <= (h_TX2 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[10] && !full_TX) h_TX3 <= (h_TX3 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[10] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_tx_ready) full_TX <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[15]))) begin
        h_RX0[31:0] <= c_rx_data[31:0];
        h_RX1[31:0] <= c_rx_data[63:32];
        h_RX2[31:0] <= c_rx_data[95:64];
        h_RX3[31:0] <= c_rx_data[127:96];
        h_RX4[5:0] <= c_rx_id[5:0];
        h_RX4[11:6] <= c_rx_cycle[5:0];
        h_RX4[18:12] <= c_rx_len[6:0];
        h_RX4[19:19] <= c_rx_null;
        h_RX4[20:20] <= c_rx_sync;
        h_RX4[21:21] <= c_rx_startup;
        avail_RX <= 1'b1;
      end else if (rd && hit[15]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_spc = r_CFG0[3:0];
  assign c_cfg_tss = r_CFG0[7:4];
  assign c_cfg_slot = r_CFG0[17:8];
  assign c_cfg_ap = r_CFG0[23:18];
  assign c_cfg_nslots = r_CFG0[29:24];
  assign c_cfg_nit = r_CFG1[9:0];
  assign c_cfg_plen = r_CFG1[13:10];
  assign c_cfg_my_slot = r_CFG1[19:14];
  assign c_cfg_sync = r_CFG1[20:20];
  assign c_cfg_cold = r_CFG1[21:21];
  assign c_cfg_chan_b = r_CFG1[22:22];
  assign c_cfg_corr = r_CFG1[30:23];
  assign c_tx_data[31:0] = h_TX0[31:0];
  assign c_tx_data[63:32] = h_TX1[31:0];
  assign c_tx_data[95:64] = h_TX2[31:0];
  assign c_tx_data[127:96] = h_TX3[31:0];
  assign c_tx_valid = full_TX;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_cycle_start;
    irq_set[1] = c_tx_done;
    irq_set[2] = c_err_coding;
    irq_set[3] = c_err_hcrc;
    irq_set[4] = c_err_fcrc;
    irq_set[5] = c_err_slot;
    irq_set[6] = c_err_sync;
    irq_set[7] = full_TX & c_tx_ready;
    irq_set[8] = wr & (hit[7] | hit[8] | hit[9] | hit[10]) & full_TX;
    irq_set[9] = c_rx_valid & (~avail_RX | (rd & hit[15]));
    irq_set[10] = c_rx_valid & avail_RX & ~(rd & hit[15]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RX, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CFG0);
      10'd6: apb_rdata = 32'(r_CFG1);
      10'd7: apb_rdata = 32'(h_TX0);
      10'd8: apb_rdata = 32'(h_TX1);
      10'd9: apb_rdata = 32'(h_TX2);
      10'd10: apb_rdata = 32'(h_TX3);
      10'd11: apb_rdata = 32'(h_RX0);
      10'd12: apb_rdata = 32'(h_RX1);
      10'd13: apb_rdata = 32'(h_RX2);
      10'd14: apb_rdata = 32'(h_RX3);
      10'd15: apb_rdata = 32'(h_RX4);
      10'd16: apb_rdata = 32'({c_slot, c_cycle, c_synced});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
